from bisect import insort

class SORTracker:
    def __init__(self):
        self.data = []
        self.q = 0

    def add(self, name: str, score: int) -> None:
        insort(self.data, (-score, name))

    def get(self) -> str:
        name = self.data[self.q][1]
        self.q += 1
        return name

