class SORTracker {
    private static class Key {
        int score;
        String name;
        Key(int score, String name) { this.score = score; this.name = name; }
    }

    private static final Comparator<Key> CMP = (a, b) ->
        a.score != b.score ? Integer.compare(b.score, a.score) : a.name.compareTo(b.name);

    private final List<Key> data = new ArrayList<>();
    private int q = 0;

    public SORTracker() {}

    public void add(String name, int score) {
        Key key = new Key(score, name);
        int pos = Collections.binarySearch(data, key, CMP);
        if (pos < 0) pos = -pos - 1;
        data.add(pos, key);
    }

    public String get() {
        return data.get(q++).name;
    }
}

