};

SORTracker.prototype.add = function(name, score) {
    const key = [-score, name];
    let lo = 0, hi = this.data.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (this.less(this.data[mid], key)) lo = mid + 1;
        else hi = mid;
    }
    this.data.splice(lo, 0, key);
};

SORTracker.prototype.get = function() {
    return this.data[this.q++][1];
};

