import heapq

class SORTracker:
    def __init__(self):
        self.reported = []  # min-heap whose root is the WORST already-returned location
        self.pending = []   # min-heap of (-score, name): root = best location

    def add(self, name: str, score: int) -> None:
        if self.reported and (-score, name) < self.reported[0].key:
            worst = heapq.heapreplace(self.reported, SORTracker._Entry(score, name))
            heapq.heappush(self.pending, (-worst.score, worst.name))
        else:
            heapq.heappush(self.pending, (-score, name))

    def get(self) -> str:
        neg, name = heapq.heappop(self.pending)
        heapq.heappush(self.reported, SORTracker._Entry(-neg, name))
        return name

    class _Entry:
        __slots__ = ('score', 'name', 'key')
        def __init__(self, score, name):
            self.score = score
            self.name = name
            self.key = (-score, name)
        def __lt__(self, other):
            return self.key > other.key

