class SORTracker {
    struct Loc {
        int score;
        string name;
        bool operator<(const Loc& o) const {
            return score != o.score ? score > o.score : name < o.name;
        }
    };
    multiset<Loc> reported;  // ordered best -> worst; *rbegin() is the worst reported
    multiset<Loc> pending;   // ordered best -> worst; *begin() is the next to report
public:
    SORTracker() {}

    void add(string name, int score) {
        Loc loc{score, move(name)};
        if (!reported.empty() && loc < *prev(reported.end())) {
            auto worst = prev(reported.end());
            pending.insert(*worst);
            reported.erase(worst);
            reported.insert(move(loc));
        } else {
            pending.insert(move(loc));
        }
    }

    string get() {
        auto it = pending.begin();
        reported.insert(*it);
        string res = it->name;
        pending.erase(it);
        return res;
    }
};

