class SORTracker {
    private record Loc(int score, String name) {}

    private static final Comparator<Loc> BETTER =
        Comparator.comparingInt(Loc::score).reversed().thenComparing(Loc::name);

    private final PriorityQueue<Loc> reported = new PriorityQueue<>(BETTER.reversed()); // root = worst reported
    private final PriorityQueue<Loc> pending = new PriorityQueue<>(BETTER);             // root = best pending

    public SORTracker() {}

    public void add(String name, int score) {
        Loc loc = new Loc(score, name);
        if (!reported.isEmpty() && BETTER.compare(loc, reported.peek()) < 0) {
            pending.offer(reported.poll());
            reported.offer(loc);
        } else {
            pending.offer(loc);
        }
    }

    public String get() {
        Loc loc = pending.poll();
        reported.offer(loc);
        return loc.name();
    }
}

