var SORTracker = function() {
    this.reported = [];  // worse-first min-heap: root = worst already-returned
    this.pending = [];   // better-first min-heap: root = next to report
};

SORTracker.prototype.better = function(a, b) {
    return a[0] > b[0] || (a[0] === b[0] && a[1] < b[1]);
};

SORTracker.prototype.push = function(h, item, better) {
    h.push(item);
    let i = h.length - 1;
    while (i > 0) {
        const p = (i - 1) >> 1;
        if (!better(h[i], h[p])) break;
        [h[i], h[p]] = [h[p], h[i]];
        i = p;
    }
};

SORTracker.prototype.pop = function(h, better) {
    const top = h[0];
    const last = h.pop();
    if (h.length > 0) {
        h[0] = last;
        let i = 0;
        for (;;) {
            let m = i;
            const l = 2 * i + 1, r = l + 1;
            if (l < h.length && better(h[l], h[m])) m = l;
            if (r < h.length && better(h[r], h[m])) m = r;
            if (m === i) break;
            [h[i], h[m]] = [h[m], h[i]];
            i = m;
        }
    }
    return top;
};

SORTracker.prototype.add = function(name, score) {
    const loc = [score, name];
    const self = this;
    const byBetter = (x, y) => self.better(x, y);
    const byWorse = (x, y) => self.better(y, x);
    if (this.reported.length && this.better(loc, this.reported[0])) {
        this.push(this.pending, this.pop(this.reported, byWorse), byBetter);
        this.push(this.reported, loc, byWorse);
    } else {
        this.push(this.pending, loc, byBetter);
    }
};

SORTracker.prototype.get = function() {
    const self = this;
    const loc = this.pop(this.pending, (x, y) => self.better(x, y));
    this.push(this.reported, loc, (x, y) => self.better(y, x));
    return loc[1];
};
